INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '202832ab-8377-594c-99b6-78d08f9f460a', 'f87ce9ec-fd40-5a30-8723-defed9ea7e4a',
  'Với mỗi dãy khoá dưới đây, lần lượt thêm vào một bảng băm (rỗng) có kích thước là 19, với hàm băm là $h(k) = k\%19$, dãy khoá nào xảy ra ít đụng độ nhất?

