INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '87d3e63a-8d9c-5472-be46-d06c33303246', 'f87ce9ec-fd40-5a30-8723-defed9ea7e4a',
  '**12. [2.2E]** Xét một Danh sách liên kết đơn được biểu diễn bởi 2 con trỏ `head`, `tail`, lần lượt chứa địa chỉ của Node đầu tiên và Node cuối cùng trong Danh sách liên kết. Giả sử hiện tại Danh sách chỉ có 1 phần tử. Phát biểu nào sau đây là đúng sau khi xoá 1 Node ở vị trí cuối cùng?

